from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_1 = Integer(1); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_1p0 = RealNumber('1.0')# H1_H2_via_hatZ_hatY:
#   H_1^{(±)} = (1/M) Σ_{j=1}^{M} hatY_j hatZ^{(±)}_{-j} exp(-i 2πj/M)
#   H_2       = (1/M) Σ_{j=1}^{M} hatZ^{(-)}_{-j} hatY_j
#
# 独立経路:
#   左辺（実空間側）: H1_op / H2_op = Y_m Z_{m+1} などの積和として直接構成
#   右辺（Fourier 側）: hatY_op / hatZ_op の積を j について足し上げる
# 2 つは全く別の作り方なので一致は非自明。
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

rep = CheckReport("H1_H2_via_hatZ_hatY: H_1^{(±)}, H_2 の hat による表示")

M_LIST = [_sage_const_2 , _sage_const_3 , _sage_const_4 , _sage_const_5 ]

for M in M_LIST:
    Mi = int(M)

    for sign in ['+', '-']:
        rhs = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
        for j in range(_sage_const_1 , Mi + _sage_const_1 ):
            rhs = rhs + (hatY_op(j, M) @ hatZ_op(-j, M, sign))                 * _np.exp(-_sage_const_1j  * _sage_const_2  * _np.pi * float(j) / float(Mi))
        rhs = rhs / float(Mi)
        rep.close(H1_op(M, sign), rhs, "M=%d sign=%s: H_1^{(±)} の hat 表示" % (M, sign))

    rhs2 = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
    for j in range(_sage_const_1 , Mi + _sage_const_1 ):
        rhs2 = rhs2 + (hatZ_op(-j, M, '-') @ hatY_op(j, M))
    rhs2 = rhs2 / float(Mi)
    rep.close(H2_op(M), rhs2, "M=%d: H_2 の hat 表示" % M)

    # 定義側の確認: H_1^{(±)} の最後の項の符号が ∓ であること
    #   H_1^{(±)} = Y_1Z_2 + … + Y_{M-1}Z_M ∓ Y_M Z_1
    for sign in ['+', '-']:
        expl = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
        for m in range(_sage_const_1 , Mi):
            expl = expl + Yop(m, M) @ Zop(m + _sage_const_1 , M)
        expl = expl + (-_sage_const_1p0  if sign == '+' else +_sage_const_1p0 ) * (Yop(Mi, M) @ Zop(_sage_const_1 , M))
        rep.close(H1_op(M, sign), expl, "M=%d sign=%s: H_1 の定義式" % (M, sign))
    expl2 = _np.zeros((_sage_const_2  ** Mi, _sage_const_2  ** Mi), dtype=complex)
    for m in range(_sage_const_1 , Mi + _sage_const_1 ):
        expl2 = expl2 + Zop(m, M) @ Yop(m, M)
    rep.close(H2_op(M), expl2, "M=%d: H_2 の定義式" % M)

rep.finish()

